'use client'

import { useRouter } from 'next/navigation'

export interface Comment {
  id: number
  name: string
  body: string
  email: string
}

export interface BlogPostDetail {
  id: number
  title: string
  body: string
}

export interface BlogPostClientProps {
  post: BlogPostDetail
  comments: Comment[]
}

export default function BlogPostClient({
  post,
  comments,
}: BlogPostClientProps) {
  const router = useRouter()

  return (
    <article>
      <button onClick={() => router.back()}>&larr; Back</button>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import BlogPostClient, {
  type BlogPostDetail,
  type Comment,
} from './blog-post'

interface RouteParams {
  id: string
}

export const dynamicParams = true

export const revalidate = 300

export async function generateStaticParams(): Promise<RouteParams[]> {
  const res = await fetch('https://jsonplaceholder.typicode.com/posts')
  const posts: Array<{ id: number }> = await res.json()

  return posts.slice(0, 10).map((post) => ({ id: post.id.toString() }))
}

async function getPost(id: string): Promise<BlogPostDetail | null> {
  const res = await fetch(
    `https://jsonplaceholder.typicode.com/posts/${id}`,
    { next: { revalidate } }
  )
  if (!res.ok) return null
  return res.json()
}

async function getComments(id: string): Promise<Comment[]> {
  const res = await fetch(
    `https://jsonplaceholder.typicode.com/posts/${id}/comments`,
    { next: { revalidate } }
  )
  if (!res.ok) return []
  return res.json()
}

export async function generateMetadata({
  params,
}: {
  params: Promise<RouteParams>
}): Promise<Metadata> {
  const { id } = await params

  try {
    const post = await getPost(id)
    if (!post) {
      return { title: 'Post Not Found' }
    }
    const description = post.body.substring(0, 160)
    return {
      title: post.title,
      description,
      openGraph: {
        title: post.title,
        description,
      },
    }
  } catch {
    return { title: 'Post Not Found' }
  }
}

export default async function BlogPostPage({
  params,
}: {
  params: Promise<RouteParams>
}) {
  const { id } = await params

  let post: BlogPostDetail | null = null
  let comments: Comment[] = []
  try {
    ;[post, comments] = await Promise.all([getPost(id), getComments(id)])
  } catch {
    notFound()
  }

  if (!post) {
    notFound()
  }

  return <BlogPostClient post={post} comments={comments} />
}

