interface Post {
  id: number
  title: string
  content: string
  createdAt?: string
  updatedAt?: string
}

interface RouteContext {
  params: Promise<{ id: string }>
}

export async function GET(
  _request: Request,
  { params }: RouteContext
): Promise<Response> {
  const { id } = await params

  const post: Post = {
    id: parseInt(id),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return Response.json(post)
}

interface UpdatePostBody {
  title?: string
  content?: string
}

export async function PUT(
  request: Request,
  { params }: RouteContext
): Promise<Response> {
  const { id } = await params
  const { title, content } = (await request.json()) as UpdatePostBody

  const updatedPost: Post = {
    id: parseInt(id),
    title: title ?? `Post ${id}`,
    content: content ?? `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(updatedPost)
}

export async function DELETE(
  _request: Request,
  { params }: RouteContext
): Promise<Response> {
  const { id } = await params

  return Response.json({ message: `Post ${id} deleted successfully` })
}

